import json,time
from pathlib import Path
import numpy as np
import wfdb
from scipy.signal import resample_poly
from develop_v4a_qrs_gate import ROOT,OUT,assign,gate,aggregate,features
def main():
 r=json.loads((OUT/'evaluation.json').read_text());groups=r['design']['groups'];t=r['gate_locked']['selected_threshold'];v=[];checks=0
 inc=np.load(ROOT/'data/processed/incart_v4_250hz.npz')
 for p in sorted(OUT.glob('*_features.npz')):
  ds,rec=p.stem.replace('_features','').split('_',1);z=np.load(p);group=rec if ds=='MITBIH' else str(inc['patient_ids'][np.flatnonzero(inc['record_ids']==rec)[0]]);role=next(k for k,x in groups.items() if group in x[ds]);peaks=z['peaks'];m,_=assign(z['ref'],peaks);j=np.array([int(m[i]) for i,c in enumerate(z['symbols']) if c=='V' and m[i]>=0],dtype=int)
  if not len(j):continue
  base=ROOT/('files' if ds=='INCART' else 'mit-bih-arrhythmia-database-1.0.0')/rec;h=wfdb.rdheader(str(base));ch=[n.strip().upper() for n in h.sig_name].index('II' if ds=='INCART' else 'MLII');sig=resample_poly(wfdb.rdrecord(str(base),channels=[ch]).p_signal[:,0],250 if ds=='INCART' else 25,257 if ds=='INCART' else 36)
  raw=np.clip(np.rint(2048+200*sig),0,4095);keep=~((z['ratio']<t)&(z['offset']>40))
  for idx in j:
   center=int(peaks[idx]);w=sig[center-64:center+64];amp=abs(w-np.median(w));width=np.sum(amp>=.5*max(amp))*4;rr=(center-peaks[idx-1])/250 if idx else 1.
   v.append(dict(dataset=ds,record=rec,role=role,ptp=float(np.ptp(w)),half_amplitude_support_ms=float(width),RR=float(rr),rejected=not bool(keep[idx])))
  # Validate streaming O(n) energy computation against saved vectorized gate.
  for center in peaks[:2]:
   w=raw[center-128:center+128];energy=np.diff(w)**2;ring=list(energy[:48]);running=sum(ring);maximum=running;at=0
   for start in range(1,208):
    running+=energy[start+47]-energy[start-1]
    if running>maximum:maximum=running;at=start
   central=sum(energy[104:152]);decision=not (maximum>1e-12 and central<t*maximum and abs(at+24-128)>40)
   rr0,oo=features(np.asarray(w)[None,:]);assert decision==bool(~((rr0<t)&(oo>40))[0]);checks+=1
 fit=[x for x in v if x['role']=='Fit'];low=float(np.percentile([x['ptp'] for x in fit],10));broad=float(np.percentile([x['half_amplitude_support_ms'] for x in fit],90));strata={}
 for ds in ['MITBIH','INCART']:
  a=[x for x in v if x['role']=='Evaluation' and x['dataset']==ds];strata[ds]={}
  for name,pred in [('all_matched_PVC',lambda x:True),('low_amplitude_Fit_q10',lambda x:x['ptp']<=low),('broad_half_amplitude_support_Fit_q90',lambda x:x['half_amplitude_support_ms']>=broad),('short_detected_RR_lt600ms',lambda x:x['RR']<.6)]:
   s=[x for x in a if pred(x)];strata[ds][name]={'samples':len(s),'rejected':sum(x['rejected'] for x in s)}
 diagnostic={'definitions':'Morphology proxies only: central128 peak-to-peak in mV; number of samples over half absolute deviation from median, not clinical QRS duration. Cutoffs from Fit only. Descriptive strata, no parameter selection.','Fit_low_ptp_q10':low,'Fit_broad_support_q90_ms':broad,'evaluation':strata,'streaming_decisions_checked':checks}
 (OUT/'PVC_subgroup_checks.json').write_text(json.dumps(diagnostic,indent=2))
 decision={'aggregate_acceptance':r['status'],'final_decision':'FAIL for promotion/stable multi-group improvement; keep V4 baseline','reason':'Only2/16 MIT records and3/29 INCART records show FP/F1 benefit;71/73 INCART FP improvement is one record I16(patient8); no real Evaluation PVC rejected, but tiny MIT benefit and concentration do not establish stable patient-level improvement','no_more_variants':True}
 (OUT/'decision.json').write_text(json.dumps(decision,indent=2))
 lines=['# V4-A QRS verification experiment','','Final recommendation: **keep V4 baseline**. Aggregate gate acceptance criterion passed, but stable multi-patient benefit is not established, so promotion is FAIL. No additional gate variants or Test evaluation were run.','','V4 only:849 parameters, model SHA256 '+r['design']['model_sha256']+', threshold0.88, ECG250Hz/256 samples/window-zscore, no RR. Firmware/detector/model unchanged.','','## Split and selection','','37 Fit records,19 Calibration records,45 Evaluation records, disjoint MIT record/INCART patient groups (see design.json). Uses locked CV fold0 grouping: Fit folds3+4, Calibration2, Evaluation0+1. Gate family/grid/split frozen before new processing; threshold locked before Evaluation feature/inference processing. Evaluation groups were used historically in V1–V11 and some waveform examples informed the research hypothesis, so this is internally held-out gate-parameter evaluation, not a fresh independent cohort. MIT record groups are proxies, not proven distinct patients.','','Gate rejects only if central48-sample squared-difference energy / strongest48-sample energy <0.05 AND strongest support center offset>40samples. It requires a dominant off-center component; no absolute slope or RR cutoff. Runtime has no annotation/label access. Candidate thresholds0,.05,.1,.2,.3. Fit allows at most0.1% matched-PVC rejection; Calibration requires zero matched-PVC rejection, no FN/F1 worsening per dataset. Threshold0.05 reduced2 calibration FP; stronger thresholds rejected PVC and were not selected.','','## Evaluation — held out from gate parameter selection','','| Dataset | Mode | Precision | Recall PVC | F1 | TP | FP | FN | TN | FP/1000 N | Peak sensitivity | Peak PPV | Gate-rejected PVC |','|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for mode,dsrows in r['summary']['Evaluation'].items():
  for ds,x in dsrows.items():lines.append(f"| {ds} | {mode} | {100*x['precision']:.4f}% | {100*x['recall']:.4f}% | {100*x['f1']:.4f}% | {x['TP']} | {x['FP']} | {x['FN']} | {x['TN']} | {x['fp_per_1000_N']:.3f} | {100*x['peak_sensitivity']:.4f}% | {100*x['peak_ppv']:.4f}% | {x['rejected_true_PVC']} |")
 lines+=['','MIT FP1510→1506, INC1938→1865. PVC recall unchanged. INC rejects7 matched N (additional missing-N abstentions), not PVC. Baseline FP source: MIT1465/1510 matched-N classification errors; INC681/1938 matched-N errors and1257 unmatched alarms. Gate does not address the dominant MIT CNN classification errors. Improvements only MIT106(2FP),112(2FP); INC I16(71FP),I17(1FP),I47(1FP). All other evaluation records have unchanged F1; no record F1 worsened. Most INC benefit is patient8.','','## Diagnosis and safeguards','','Train/Development waveform evidence and scope analysis reused from results/cnn_v11/unmatched_peak_analysis/. Some INCART candidates are broad T-wave-compatible events after a separately detected QRS. Other unmatched peaks may be timing errors, secondary lobes, unannotated events or rhythm-scope markers; do not call all noise. Matched OTHER count as peak TP and are excluded from N/V classification. Gate does not use labels, annotations, patient ID, CNN score or future samples beyond the ready window.','','The main MIT Development FP burden is on matched Normal QRS, beyond the scope of a verification-only gate. INCART has more unmatched alarms. This distinction is reflected separately in evaluation.json. QRS validity/T/P/noise adjudication remains incomplete; gate rejection is not a physiological ground truth label.','','All missed V, including gate-caused misses, are included FN. Missing N separately reported, not TN. Unmatched predicted PVC count FP. Matching is re-applied one-to-one unchanged at +/-38 samples after gating; OTHER never relabeled Normal. Peaks matching rhythm markers outside BEATS are still scope-unmatched under the unchanged metric. Synthetic ADC, ungated baseline stream; not complete firmware quality-gated performance.','','## PVC safety strata','',json.dumps(diagnostic,indent=2),'','These strata include only baseline-detected matched PVC; baseline missed PVC remain separately counted FN. Width is an amplitude-support proxy, not adjudicated QRS width. No real PVC in Evaluation was rejected; this does not prove preservation on unseen patients.','','## Timing, CPU and RAM','','Decision waits for existing center+127 (508ms postpeak); no additional latency beyond the ready256-sample window. FIFO candidate confirmation can be50 samples but gate requires complete window. A single streaming scan needs255 differences/squares, about460 rolling-sum operations, about208 comparisons and central support accumulation: O(256), roughly1–2k scalar operations per beat, no sqrt/trigonometry, no dynamic allocation. Comparison central<t*maximum avoids division. 48-value energy ring requires192bytes using float32, plus scalar state, reusing existing1024-byte ECG window. Current host vectorized implementation uses larger arrays; this is a proposed bounded embedded implementation, not measured ESP32 RAM/latency. Streaming decision check uses float64/integer ADC energy, so float32 embedded parity still pending. No board timing claims.','','## Per-record Evaluation results','','| Dataset | Record | Patient/group | Mode | F1 | TP | FP | FN | Gate PVC rejected |','|---|---|---|---|---:|---:|---:|---:|---:|']
 for x in sorted([v for v in r['records'] if v['role']=='Evaluation'],key=lambda x:(x['dataset'],x['record'],x['mode'])):
  m=aggregate([{k:v for k,v in x.items() if k not in ['dataset','record','group','role','mode']}]);lines.append(f"| {x['dataset']} | {x['record']} | {x['group']} | {x['mode']} | {100*m['f1']:.3f}% | {x['TP']} | {x['FP']} | {x['FN']} | {x['rejected_true_PVC']} |")
 lines+=['','## Worst Evaluation group','']
 groupmetrics=[]
 for ds in ['MITBIH','INCART']:
  for mode in ['baseline','V4-A']:
   values=[]
   for group in sorted(set(x['group'] for x in r['records'] if x['role']=='Evaluation' and x['dataset']==ds)):
    a=[{k:v for k,v in x.items() if k not in ['dataset','record','group','role','mode']} for x in r['records'] if x['role']=='Evaluation' and x['dataset']==ds and x['mode']==mode and x['group']==group];m=aggregate(a);values.append((group,m));groupmetrics.append(dict(dataset=ds,mode=mode,group=group,**m))
   worst=min(values,key=lambda a:a[1]['f1']);lines.append(f"{ds} {mode}: group{worst[0]}, F1{100*worst[1]['f1']:.3f}%.")
 (OUT/'group_metrics.json').write_text(json.dumps(groupmetrics,indent=2));(OUT/'report.md').write_text('\n'.join(lines),encoding='utf-8');print(json.dumps(diagnostic,indent=2));print(json.dumps(decision,indent=2))
if __name__=='__main__':main()
